<div class="grid-2"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Corrective-action collaboration</span><h2>Submit quality response</h2><p>Supplier closure does not close an internal quality event. Internal verification remains required.</p></div></header><?php if(supplier_portal_can($account,'quality')): ?><form class="form-grid" method="post" action="<?= h(root_url('supplier-portal/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="submit_quality"><input type="hidden" name="return_tab" value="quality"><label><span>Quality reference</span><input name="quality_reference" required></label><label><span>Response type</span><select name="response_type"><option value="containment">Containment</option><option value="root_cause">Root cause</option><option value="corrective_action">Corrective action</option><option value="preventive_action">Preventive action</option><option value="complete_response">Complete response</option></select></label><label class="span-2"><span>Containment response</span><textarea name="containment_response" required></textarea></label><label class="span-2"><span>Root cause</span><textarea name="root_cause" required></textarea></label><label class="span-2"><span>Corrective action</span><textarea name="corrective_action" required></textarea></label><label class="span-2"><span>Preventive action</span><textarea name="preventive_action" required></textarea></label><label><span>Target date</span><input type="date" name="target_date" value="<?= date('Y-m-d',strtotime('+14 days')) ?>" required></label><label><span>Evidence reference</span><input name="evidence_reference" required></label><div class="span-2"><button class="button primary">Submit quality response</button></div></form><?php endif; ?></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Quality history</span><h2>Responses and review status</h2></div></header><div class="record-list"><?php foreach($quality as $response): ?><article class="record-card"><header><div><strong><?= h($response['quality_reference']) ?></strong><small><?= h($response['response_number']) ?> · Target <?= h(date_us($response['target_date'])) ?></small></div><span class="status <?= h($response['status']) ?>"><?= h(status_label($response['status'])) ?></span></header><p><?= h($response['review_note']??'Awaiting internal verification.') ?></p></article><?php endforeach; ?></div></section></div>
